function SacredGeometry() {
  const toR = d => (d * Math.PI) / 180;
  const pts = [[400,400],[400,316],[400,484],[469,358],[331,358],[469,442],[331,442],[538,400],[262,400]];
  const met = [0,1,2,3,4,5].map(i => ({ x2:400+Math.cos(toR(i*60-90))*336, y2:400+Math.sin(toR(i*60-90))*336 }));
  return (
    <svg viewBox="0 0 800 800" xmlns="http://www.w3.org/2000/svg" style={{width:"100%",height:"100%",opacity:.06}}>
      {pts.map(([cx,cy],i) => <circle key={i} cx={cx} cy={cy} r="84" fill="none" stroke="#ffd700" strokeWidth=".55"/>)}
      <circle cx="400" cy="400" r="252" fill="none" stroke="#ffd700" strokeWidth=".4"/>
      <circle cx="400" cy="400" r="336" fill="none" stroke="#ffd700" strokeWidth=".28"/>
      <circle cx="400" cy="400" r="400" fill="none" stroke="#ffd700" strokeWidth=".16"/>
      <polygon points="400,176 512,364 288,364" fill="none" stroke="#ffd700" strokeWidth=".55"/>
      <polygon points="400,624 288,436 512,436" fill="none" stroke="#ffd700" strokeWidth=".55"/>
      <polygon points="400,316 469,358 469,442 400,484 331,442 331,358" fill="none" stroke="#ffd700" strokeWidth=".85"/>
      {met.map((m,i) => <line key={i} x1="400" y1="400" x2={m.x2} y2={m.y2} stroke="#ffd700" strokeWidth=".18"/>)}
    </svg>
  );
}

function SunIcon({ rays }) {
  return (
    <svg viewBox="0 0 100 100" style={{width:"100%",height:"100%"}}>
      {rays > 6 && <circle cx="50" cy="50" r="15" fill="none" stroke="currentColor" strokeWidth="1.2"/>}
      {rays > 8 && <circle cx="50" cy="50" r="22" fill="none" stroke="currentColor" strokeWidth=".8"/>}
      <circle cx="50" cy="50" r={rays>6?8:12} fill="none" stroke="currentColor" strokeWidth="1.5"/>
      <circle cx="50" cy="50" r={rays>6?3:5} fill="currentColor"/>
      {Array.from({length:rays},(_,i) => {
        const a = (360/rays)*i, toR = d=>(d*Math.PI)/180;
        const r1 = rays>6?26:16, r2 = rays>6?38:28;
        return <line key={i} x1={50+r1*Math.cos(toR(a))} y1={50+r1*Math.sin(toR(a))} x2={50+r2*Math.cos(toR(a))} y2={50+r2*Math.sin(toR(a))} stroke="currentColor" strokeWidth="1.5"/>;
      })}
    </svg>
  );
}

function CountdownTimer() {
  const [t, setT] = useState({d:0,h:0,m:0,s:0});
  useEffect(() => {
    const target = new Date(); target.setDate(target.getDate()+14); target.setHours(12,0,0,0);
    const tick = () => {
      const diff = target - Date.now();
      if (diff>0) setT({d:Math.floor(diff/86400000),h:Math.floor(diff/3600000)%24,m:Math.floor(diff/60000)%60,s:Math.floor(diff/1000)%60});
    };
    tick(); const id = setInterval(tick,1000); return () => clearInterval(id);
  }, []);
  return (
    <motion.div style={{display:"flex",flexDirection:"column",alignItems:"center",marginTop:"1.8rem",gap:"1rem"}}
      initial={{opacity:0,y:20}} animate={{opacity:1,y:0}} transition={{duration:1,delay:1.3}}>
      {/* Phase 1 label */}
      <div style={{display:"flex",alignItems:"center",gap:".6rem"}}>
        <div style={{width:"28px",height:"1px",background:"linear-gradient(to right,transparent,rgba(255,180,0,.45))"}}/>
        <span style={{fontFamily:"'Orbitron',monospace",fontSize:".4rem",letterSpacing:".3em",color:"rgba(255,170,0,.48)"}}>GENESIS WINDOW CLOSES IN</span>
        <div style={{width:"28px",height:"1px",background:"linear-gradient(to left,transparent,rgba(255,180,0,.45))"}}/>
      </div>
      <div style={{display:"flex",gap:"clamp(.6rem,2vw,1.2rem)"}}>
        {[{l:"SOLAR DAYS",v:t.d},{l:"HOURS",v:t.h},{l:"MINUTES",v:t.m},{l:"SECONDS",v:t.s}].map((u,i) => (
          <motion.div key={u.l} style={{display:"flex",flexDirection:"column",alignItems:"center"}}
            initial={{opacity:0,scale:.8}} animate={{opacity:1,scale:1}} transition={{delay:1.4+i*.1}}>
            <div style={{width:"clamp(52px,12vw,72px)",height:"clamp(52px,12vw,72px)",display:"flex",alignItems:"center",justifyContent:"center",borderRadius:"8px",border:"1px solid rgba(255,170,0,.38)",background:"rgba(0,0,0,.55)",backdropFilter:"blur(8px)",animation:`countdown-pulse 3s ease-in-out infinite`,animationDelay:`${i*.3}s`}}>
              <span style={{fontFamily:"'Orbitron',monospace",fontSize:"clamp(1.1rem,3.5vw,1.75rem)",fontWeight:700,background:"linear-gradient(180deg,#ffd700,#ff8c00)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>
                {String(u.v).padStart(2,"0")}
              </span>
            </div>
            <span style={{fontFamily:"'Orbitron',monospace",fontSize:".38rem",letterSpacing:".16em",color:"rgba(255,170,0,.5)",marginTop:"6px",textAlign:"center"}}>{u.l}</span>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}


