function FlashPulse() {
  const [vals,    setVals]    = useState(() => PULSE_METRICS.map(() => 0));
  const [changed, setChanged] = useState(() => PULSE_METRICS.map(() => false));
  const [blink,   setBlink]   = useState(true);

  useEffect(() => {
    // Each metric rotates on a different cadence for an organic feel
    const ids = PULSE_METRICS.map((m, i) =>
      setInterval(() => {
        setVals(prev => {
          const next = [...prev];
          next[i] = (next[i] + 1) % m.states.length;
          return next;
        });
        // Trigger the ping animation briefly on change
        setChanged(prev => {
          const n = [...prev]; n[i] = true; return n;
        });
        setTimeout(() => setChanged(prev => {
          const n = [...prev]; n[i] = false; return n;
        }), 650);
      }, 4200 + i * 1300)
    );
    const blinkId = setInterval(() => setBlink(b => !b), 850);
    return () => { ids.forEach(clearInterval); clearInterval(blinkId); };
  }, []);

  return (
    <div style={{
      display:"flex", flexDirection:"column", justifyContent:"space-between",
      background:"rgba(4,2,0,.9)", border:"1px solid rgba(255,180,0,.24)",
      borderRadius:"10px", padding:"1.1rem 1.2rem", backdropFilter:"blur(12px)",
      minWidth:"clamp(200px,38%,280px)", flexShrink:0,
      boxShadow:"inset 0 0 30px rgba(255,100,0,.05), 0 0 24px rgba(255,100,0,.07)",
      position:"relative", overflow:"hidden",
    }}>
      {/* Scanline texture */}
      <div style={{position:"absolute",inset:0,pointerEvents:"none",
        backgroundImage:"repeating-linear-gradient(0deg,rgba(255,180,0,.012) 0px,rgba(255,180,0,.012) 1px,transparent 1px,transparent 5px)",
        borderRadius:"10px"}}/>

      {/* ── Header ─────────────────────────────────────────── */}
      <div style={{marginBottom:"1rem"}}>
        <div style={{display:"flex",alignItems:"center",gap:".5rem",marginBottom:".38rem"}}>
          {/* Live blink dot */}
          <span style={{position:"relative",width:"8px",height:"8px",flexShrink:0}}>
            <span style={{position:"absolute",inset:0,borderRadius:"50%",
              background: blink ? "#ff4444":"rgba(255,80,80,.25)",
              boxShadow:  blink ? "0 0 10px #ff4444":"none",
              transition:"all .42s ease"}}/>
            {blink && <span style={{position:"absolute",inset:"-3px",borderRadius:"50%",
              border:"1px solid rgba(255,68,68,.5)",
              animation:"metric-ping .85s ease-out"}}/>}
          </span>
          <span style={{fontFamily:"'Orbitron',monospace",fontSize:".62rem",letterSpacing:".24em",
            fontWeight:700,background:"linear-gradient(90deg,#ffd700,#ff8c00)",
            WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>
            Flash Pulse
          </span>
          <span style={{fontFamily:"'Orbitron',monospace",fontSize:".4rem",letterSpacing:".18em",
            color:"rgba(255,180,0,.4)",marginLeft:"auto"}}>v1.0</span>
        </div>
        <div style={{height:"1px",background:"linear-gradient(to right,rgba(255,180,0,.35),transparent)"}}/>
      </div>

      {/* ── Metrics ────────────────────────────────────────── */}
      <div style={{display:"flex",flexDirection:"column",gap:".9rem",flex:1}}>
        {PULSE_METRICS.map((m, i) => {
          const state     = m.states[vals[i]];
          const intensity = METRIC_INTENSITY[i][vals[i]];
          const isPinged  = changed[i];
          return (
            <div key={m.label} style={{display:"flex",flexDirection:"column",gap:".28rem"}}>
              {/* Label row */}
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                <span style={{fontFamily:"'Orbitron',monospace",fontSize:".38rem",
                  letterSpacing:".2em",color:"rgba(255,180,0,.42)",textTransform:"uppercase"}}>
                  {m.label}
                </span>
                <span style={{fontFamily:"'Orbitron',monospace",fontSize:".38rem",
                  color:"rgba(255,180,0,.35)",letterSpacing:".1em"}}>
                  {Math.round(intensity * 100)}%
                </span>
              </div>

              {/* Value row with animated dot */}
              <div style={{display:"flex",alignItems:"center",gap:".45rem"}}>
                {/* Dot + ping ring */}
                <span style={{position:"relative",width:"7px",height:"7px",flexShrink:0}}>
                  <span style={{
                    position:"absolute",inset:0,borderRadius:"50%",
                    background:state.dot,
                    animation:`dot-breathe 2.4s ease-in-out infinite`,
                    "--dc": state.dot,
                    transition:"background .5s",
                  }}/>
                  {isPinged && (
                    <span style={{position:"absolute",inset:"-4px",borderRadius:"50%",
                      border:`1.5px solid ${state.dot}`,
                      animation:"metric-ping .6s ease-out forwards"}}/>
                  )}
                </span>
                {/* Value text — re-keyed on change to trigger fade-in */}
                <span key={`${i}-${vals[i]}`} style={{
                  fontFamily:"'Rajdhani',sans-serif",fontSize:".84rem",fontWeight:600,
                  letterSpacing:".06em",color:state.color,lineHeight:1.2,
                  animation:"metric-fadein .4s ease-out",
                }}>
                  {state.text}
                </span>
              </div>

              {/* Animated intensity bar */}
              <div style={{height:"3px",borderRadius:"2px",background:"rgba(255,180,0,.1)",overflow:"hidden"}}>
                <div key={`bar-${i}-${vals[i]}`} style={{
                  height:"100%", borderRadius:"2px",
                  background:`linear-gradient(to right,${state.dot},rgba(255,180,0,.4))`,
                  width:`${Math.round(intensity*100)}%`,
                  boxShadow:`0 0 6px ${state.dot}`,
                  animation:"bar-fill .7s cubic-bezier(.22,1,.36,1) forwards",
                  "--tw":`${Math.round(intensity*100)}%`,
                }}/>
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Footer ─────────────────────────────────────────── */}
      <div style={{marginTop:"1rem",paddingTop:".7rem",borderTop:"1px solid rgba(255,180,0,.1)"}}>
        <p style={{fontFamily:"'Rajdhani',sans-serif",fontSize:".66rem",
          color:"rgba(255,255,255,.2)",letterSpacing:".05em",lineHeight:1.55,margin:0}}>
          Powered by{" "}
          <span style={{color:"rgba(255,200,60,.5)",fontWeight:600}}>$FLASH Infrastructure</span>
          {" "}— Phase 2 Monitoring incoming.
        </p>
      </div>
    </div>
  );
}


