/* ─────────────── SOLAR FREQUENCY MONITOR ─────────────────────── */
const LIVE_METRICS = [
  { id:"sig",  label:"SIGNAL",       states:["STABLE","OPTIMAL","STRONG"] },
  { id:"freq", label:"FREQUENCY",    states:["432 Hz","528 Hz","963 Hz"]  },
  { id:"sol",  label:"SOLAR WIND",   states:["ACTIVE","SURGING","INTENSE"]},
  { id:"geo",  label:"GEO STORM",    states:["NONE","G1 WATCH","CLEAR"]   },
  { id:"pho",  label:"PHOTON FLUX",  states:["ELEVATED","PEAK","STABLE"]  },
];

function SolarFrequencyMonitor() {
  const canvasRef = useRef(null);
  const animRef   = useRef(null);
  const tRef      = useRef(0);
  const [tick, setTick]     = useState(0);
  const [metricVals, setMetricVals] = useState(() =>
    Object.fromEntries(LIVE_METRICS.map(m => [m.id, 0]))
  );

  // Randomise metrics every 3.5s to simulate live data
  useEffect(() => {
    const id = setInterval(() => {
      setMetricVals(Object.fromEntries(LIVE_METRICS.map(m => [m.id, Math.floor(Math.random()*m.states.length)])));
      setTick(t => t+1);
    }, 3500);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    let started = false;

    // Reads live canvas CSS dimensions each frame — never stale
    const getSize = () => ({
      w: canvas.offsetWidth  || canvas.parentElement?.offsetWidth || 400,
      h: canvas.offsetHeight || 180,
    });

    const syncSize = () => {
      const dpr = window.devicePixelRatio || 1;
      const { w, h } = getSize();
      if (w > 0 && h > 0) {
        canvas.width  = w * dpr;
        canvas.height = h * dpr;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
    };

    const WAVE_DEFS = [
      { freqM:2.1,  speed:0.9,  phase:0,    ampM:0.18, color:"rgba(255,180,0,.55)",  lw:1.8 },
      { freqM:3.7,  speed:1.5,  phase:1.2,  ampM:0.11, color:"rgba(255,120,0,.35)",  lw:1.2 },
      { freqM:5.9,  speed:2.2,  phase:2.5,  ampM:0.08, color:"rgba(255,220,80,.28)", lw:1.0 },
      { freqM:11.3, speed:3.1,  phase:0.8,  ampM:0.05, color:"rgba(255,80,0,.2)",    lw:0.8 },
    ];

    const drawGrid = (w, h) => {
      ctx.strokeStyle = "rgba(255,180,0,.06)";
      ctx.lineWidth   = 1;
      const cols = 12, rows = 6;
      for (let i=0;i<=cols;i++) { ctx.beginPath(); ctx.moveTo(i/cols*w,0); ctx.lineTo(i/cols*w,h); ctx.stroke(); }
      for (let j=0;j<=rows;j++) { ctx.beginPath(); ctx.moveTo(0,j/rows*h); ctx.lineTo(w,j/rows*h); ctx.stroke(); }
      ctx.strokeStyle = "rgba(255,180,0,.13)"; ctx.lineWidth = 1;
      ctx.setLineDash([4,6]);
      ctx.beginPath(); ctx.moveTo(0,h/2); ctx.lineTo(w,h/2); ctx.stroke();
      ctx.setLineDash([]);
    };

    const drawWave = (def, w, h, t) => {
      const amp = h * def.ampM;
      ctx.beginPath();
      ctx.strokeStyle = def.color; ctx.lineWidth = def.lw;
      for (let i=0;i<=180;i++) {
        const x = (i/180)*w;
        const y = h/2 + amp*Math.sin(def.freqM*Math.PI*2*(i/180)+def.phase+t*def.speed)
                      + amp*0.4*Math.sin(def.freqM*1.7*Math.PI*2*(i/180)+def.phase*1.3+t*def.speed*0.7);
        i===0 ? ctx.moveTo(x,y) : ctx.lineTo(x,y);
      }
      ctx.stroke();
    };

    const drawPulse = (w, h, t) => {
      const x = (t * 55) % w;
      const grad = ctx.createLinearGradient(x-40,0,x+8,0);
      grad.addColorStop(0,"rgba(255,180,0,0)");
      grad.addColorStop(1,"rgba(255,200,60,.4)");
      ctx.fillStyle = grad; ctx.fillRect(x-40,0,48,h);
      ctx.strokeStyle = "rgba(255,220,80,.75)"; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke();
    };

    const loop = () => {
      tRef.current += 0.012;
      const t = tRef.current;
      const { w, h } = getSize();
      // If canvas internal size drifted, resync
      if (canvas.width !== w * (window.devicePixelRatio||1)) syncSize();
      ctx.clearRect(0,0,w,h);
      ctx.fillStyle = "rgba(6,3,0,1)"; ctx.fillRect(0,0,w,h);
      drawGrid(w,h);
      WAVE_DEFS.forEach(def => drawWave(def,w,h,t));
      drawPulse(w,h,t);
      animRef.current = requestAnimationFrame(loop);
    };

    const startLoop = () => {
      if (started) return;
      syncSize();
      const { w } = getSize();
      if (w === 0) return; // still not laid out
      started = true;
      animRef.current = requestAnimationFrame(loop);
    };

    // ResizeObserver keeps internal resolution in sync
    const ro = new ResizeObserver(() => { syncSize(); startLoop(); });
    ro.observe(canvas);

    // IntersectionObserver starts the loop the moment it scrolls into view
    const io = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) { startLoop(); io.disconnect(); }
    }, { threshold: 0.01 });
    io.observe(canvas);

    // Fallback: try starting after paint cycle completes
    const tid = setTimeout(startLoop, 80);

    return () => {
      cancelAnimationFrame(animRef.current);
      ro.disconnect(); io.disconnect(); clearTimeout(tid);
    };
  }, []);

  const now = new Date();
  const ts  = `${String(now.getUTCHours()).padStart(2,"0")}:${String(now.getUTCMinutes()).padStart(2,"0")}:${String(now.getUTCSeconds()).padStart(2,"0")} UTC`;

  return (
    <div style={{position:"relative",borderRadius:"8px",overflow:"hidden",border:"1px solid rgba(255,180,0,.18)",background:"rgba(0,0,0,.8)"}}>
      {/* Canvas waveform */}
      <canvas ref={canvasRef} style={{display:"block",width:"100%",height:"clamp(140px,22vw,200px)"}}/>

      {/* Top bar */}
      <div style={{position:"absolute",top:0,left:0,right:0,display:"flex",justifyContent:"space-between",alignItems:"center",padding:".5rem .9rem",background:"linear-gradient(to bottom,rgba(0,0,0,.75),transparent)"}}>
        <div style={{display:"flex",alignItems:"center",gap:".5rem"}}>
          <span style={{width:"7px",height:"7px",borderRadius:"50%",background:"#ff4444",boxShadow:"0 0 8px #ff4444",animation:"solar-pulse 1.2s ease-in-out infinite",display:"inline-block"}}/>
          <span style={{fontFamily:"'Orbitron',monospace",fontSize:".52rem",letterSpacing:".28em",color:"rgba(255,80,80,.9)"}}>LIVE</span>
        </div>
        <span style={{fontFamily:"'Orbitron',monospace",fontSize:".45rem",letterSpacing:".18em",color:"rgba(255,180,0,.38)"}}>{ts}</span>
        <span style={{fontFamily:"'Orbitron',monospace",fontSize:".45rem",letterSpacing:".18em",color:"rgba(255,180,0,.45)"}}>SOL·FREQ·MON v2.4</span>
      </div>

      {/* Metrics strip */}
      <div style={{display:"flex",flexWrap:"wrap",gap:".4rem",padding:".6rem .8rem",background:"rgba(0,0,0,.72)",borderTop:"1px solid rgba(255,180,0,.1)"}}>
        {LIVE_METRICS.map(m => {
          const val = m.states[metricVals[m.id]];
          const isHigh = /SURGE|PEAK|INTENSE|STRONG|OPTIMAL|528|963|G1/.test(val);
          return (
            <div key={m.id} style={{display:"flex",alignItems:"center",gap:".38rem",padding:".28rem .65rem",borderRadius:"4px",border:`1px solid ${isHigh?"rgba(255,120,0,.35)":"rgba(255,180,0,.14)"}`,background:isHigh?"rgba(255,80,0,.08)":"rgba(255,180,0,.04)"}}>
              <span style={{width:"5px",height:"5px",borderRadius:"50%",background:isHigh?"#ff6a00":"rgba(80,255,160,.7)",flexShrink:0,boxShadow:isHigh?"0 0 6px #ff6a00":"0 0 5px rgba(80,255,160,.6)"}}/>
              <span style={{fontFamily:"'Orbitron',monospace",fontSize:".4rem",letterSpacing:".15em",color:"rgba(255,180,0,.42)"}}>{m.label}</span>
              <span style={{fontFamily:"'Orbitron',monospace",fontSize:".46rem",letterSpacing:".1em",color:isHigh?"rgba(255,160,60,.9)":"rgba(80,255,160,.85)",fontWeight:700}}>{val}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}


