/* ──────────────── 3D TOKENOMICS SPHERE ────────────────────────── */
const TOK_FACTS = [
  {label:"TOTAL SUPPLY",  value:"1.392B",    sub:"Sun's diameter in km · Genesis supply",  accent:"#ffd700", glow:"rgba(255,200,50,.5)"},
  {label:"TAX",           value:"0% / 0%",   sub:"Zero buy tax · Zero sell tax",            accent:"#50ffa0", glow:"rgba(80,255,160,.45)"},
  {label:"LIQUIDITY",     value:"BURNED 🔥",  sub:"LP tokens permanently destroyed",         accent:"#ff5020", glow:"rgba(255,80,30,.6)"},
];

function TokenomicsSphere() {
  const ref     = useRef(null);
  const inView  = useInView(ref, {once:true, margin:"-80px"});
  const [active, setActive]   = useState(0);
  const [dragging, setDragging] = useState(false);
  const [startX,   setStartX]   = useState(0);
  const [rotY, setRotY]         = useState(0);
  const [autoSpin, setAutoSpin] = useState(true);
  const spinRef = useRef(null);

  // Auto-cycle every 4s when not interacting
  useEffect(() => {
    if (!autoSpin) return;
    spinRef.current = setInterval(() => setActive(a => (a+1)%3), 4000);
    return () => clearInterval(spinRef.current);
  }, [autoSpin]);

  const onDown = e => {
    setDragging(true); setAutoSpin(false); clearInterval(spinRef.current);
    setStartX(e.touches?.[0]?.clientX ?? e.clientX);
    e.currentTarget.setPointerCapture?.(e.pointerId);
  };
  const onMove = e => {
    if (!dragging) return;
    const cx = e.touches?.[0]?.clientX ?? e.clientX;
    const dx = cx - startX;
    setRotY(r => r + dx * .5);
    setStartX(cx);
  };
  const onUp = e => {
    if (!dragging) return;
    setDragging(false);
    // Snap to nearest fact based on total rotation
    const snapped = Math.round(rotY / 120) * 120;
    const idx = (((-Math.round(rotY/120)) % 3) + 3) % 3;
    setActive(idx);
    setRotY(snapped);
    setTimeout(() => setAutoSpin(true), 6000);
  };

  const fact = TOK_FACTS[active];
  const isBurned = active === 2;

  return (
    <section ref={ref} style={{position:"relative",zIndex:10,padding:"clamp(4rem,9vw,6.5rem) clamp(1rem,5vw,3rem)"}}>
      <div style={{position:"absolute",inset:0,backgroundImage:"linear-gradient(rgba(255,180,0,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,180,0,.018) 1px,transparent 1px)",backgroundSize:"72px 72px",pointerEvents:"none"}}/>
      <div style={{maxWidth:"900px",margin:"0 auto",position:"relative",zIndex:1}}>
        <motion.div style={{textAlign:"center",marginBottom:"clamp(2.5rem,5vw,3.5rem)"}}
          initial={{opacity:0,y:28}} animate={inView?{opacity:1,y:0}:{}} transition={{duration:.8}}>
          <span style={{fontFamily:"'Orbitron',monospace",fontSize:".54rem",letterSpacing:".42em",color:"rgba(255,170,0,.52)",display:"block",marginBottom:".8rem"}}>ENCODED IN THE CHAIN</span>
          <h2 style={{fontFamily:"'Orbitron',monospace",fontSize:"clamp(1.7rem,4.5vw,3rem)",fontWeight:700,letterSpacing:".1em",background:"linear-gradient(140deg,#fff,#ffd700,#ff8c00)",WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",backgroundClip:"text"}}>TOKENOMICS</h2>
          <p style={{fontFamily:"'Rajdhani',sans-serif",fontSize:".85rem",color:"rgba(255,255,255,.35)",letterSpacing:".1em",marginTop:".6rem"}}>Numbers chosen by the universe. Drag or swipe to explore.</p>
        </motion.div>

        <motion.div initial={{opacity:0,scale:.9}} animate={inView?{opacity:1,scale:1}:{}} transition={{duration:.8,delay:.2}}
          style={{display:"flex",flexDirection:"column",alignItems:"center",gap:"2.5rem"}}>
          
          {/* Sphere + Fact combined */}
          <div style={{display:"flex",alignItems:"center",gap:"clamp(1.5rem,5vw,4rem)",flexWrap:"wrap",justifyContent:"center",width:"100%"}}>
            
            {/* 3D Sphere */}
            <div
              style={{width:"clamp(200px,30vw,280px)",height:"clamp(200px,30vw,280px)",perspective:"600px",cursor:dragging?"grabbing":"grab",flexShrink:0,userSelect:"none"}}
              onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
              onTouchStart={onDown} onTouchMove={onMove} onTouchEnd={onUp}>
              <div style={{width:"100%",height:"100%",position:"relative",transformStyle:"preserve-3d",animation:autoSpin&&!dragging?"sphere-bob 4s ease-in-out infinite":"none"}}>
                {/* Core sphere glow */}
                <div style={{position:"absolute",inset:"15%",borderRadius:"50%",
                  background:`radial-gradient(circle at 35% 30%, rgba(255,200,50,.3) 0%, rgba(255,80,0,.15) 45%, rgba(0,0,0,.8) 80%)`,
                  boxShadow:isBurned?"0 0 40px rgba(255,60,0,.6),0 0 80px rgba(255,40,0,.3)":"0 0 30px rgba(255,150,0,.3),0 0 60px rgba(255,80,0,.15)",
                  transition:"box-shadow .8s ease",
                  animation:isBurned?"burned-glow 1.8s ease-in-out infinite":"none",
                }}>
                  <div style={{position:"absolute",inset:0,borderRadius:"50%",border:"1px solid rgba(255,200,80,.25)"}}/>
                </div>
                {/* Orbital rings */}
                <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
                  {[
                    {anim:"orbit-a 8s linear infinite",  color:"rgba(255,200,60,.5)"},
                    {anim:"orbit-b 12s linear infinite", color:"rgba(255,120,0,.38)"},
                    {anim:"orbit-c 16s linear infinite", color:"rgba(255,255,255,.18)"},
                  ].map((ring,i)=>(
                    <div key={i} style={{
                      position:"absolute",
                      width:`${78+i*14}%`, height:`${78+i*14}%`,
                      borderRadius:"50%",
                      border:`1.5px solid ${ring.color}`,
                      animation:ring.anim,
                      boxShadow:`0 0 6px ${ring.color}`,
                    }}/>
                  ))}
                </div>
                {/* Center symbol */}
                <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:".2rem"}}>
                  <span style={{fontFamily:"'Orbitron',monospace",fontSize:"clamp(1rem,3vw,1.4rem)",fontWeight:900,color:"rgba(255,220,100,.9)",textShadow:"0 0 20px rgba(255,180,0,.6)"}}>$FLASH</span>
                  <span style={{fontFamily:"'Orbitron',monospace",fontSize:".45rem",letterSpacing:".25em",color:"rgba(255,180,0,.5)"}}>⊙ SOL</span>
                </div>
                {/* Nav dots */}
                <div style={{position:"absolute",bottom:"-2rem",left:"50%",transform:"translateX(-50%)",display:"flex",gap:".6rem"}}>
                  {TOK_FACTS.map((_,i)=>(
                    <span key={i} onClick={()=>{setActive(i);setAutoSpin(false);setTimeout(()=>setAutoSpin(true),6000);}}
                      style={{width:"7px",height:"7px",borderRadius:"50%",cursor:"pointer",transition:"all .3s",
                        background:i===active?TOK_FACTS[i].accent:"rgba(255,180,0,.2)",
                        boxShadow:i===active?`0 0 8px ${TOK_FACTS[i].accent}`:"none"}}/>
                  ))}
                </div>
              </div>
            </div>

            {/* Active fact panel */}
            <div key={active} style={{
              flex:1, minWidth:"220px", maxWidth:"360px",
              padding:"2rem 1.8rem",
              borderRadius:"14px",
              border:`1px solid ${fact.accent}44`,
              background:"rgba(0,0,0,.55)",
              backdropFilter:"blur(12px)",
              boxShadow:`0 0 40px ${fact.glow}30`,
              animation:"fact-in .5s ease",
              textAlign:"center",
            }}>
              <span style={{fontFamily:"'Orbitron',monospace",fontSize:".48rem",letterSpacing:".35em",color:`${fact.accent}aa`,display:"block",marginBottom:"1rem"}}>{fact.label}</span>
              <p style={{
                fontFamily:"'Orbitron',monospace",
                fontSize:"clamp(1.6rem,5vw,2.6rem)",
                fontWeight:900,
                color:fact.accent,
                letterSpacing:".05em",
                lineHeight:1.1,
                marginBottom:"1rem",
                textShadow:`0 0 30px ${fact.glow}`,
                animation:isBurned?"burned-glow 1.8s ease-in-out infinite":"none",
              }}>{fact.value}</p>
              <p style={{fontFamily:"'Rajdhani',sans-serif",fontSize:".88rem",color:"rgba(255,255,255,.42)",letterSpacing:".08em",lineHeight:1.6}}>{fact.sub}</p>
              {isBurned && (
                <div style={{marginTop:"1.2rem",padding:".5rem 1rem",borderRadius:"6px",background:"rgba(255,60,0,.12)",border:"1px solid rgba(255,80,30,.3)"}}>
                  <span style={{fontFamily:"'Orbitron',monospace",fontSize:".46rem",letterSpacing:".2em",color:"rgba(255,120,60,.85)"}}>LP TOKENS PERMANENTLY DESTROYED</span>
                </div>
              )}
            </div>
          </div>

          {/* Bottom mini-stats strip */}
          <div style={{display:"flex",gap:"1rem",flexWrap:"wrap",justifyContent:"center"}}>
            {TOK_FACTS.map((f,i)=>(
              <div key={i} onClick={()=>{setActive(i);setAutoSpin(false);setTimeout(()=>setAutoSpin(true),6000);}}
                style={{padding:".6rem 1.4rem",borderRadius:"8px",border:`1px solid ${i===active?f.accent+"88":"rgba(255,180,0,.12)"}`,background:i===active?"rgba(255,180,0,.06)":"rgba(0,0,0,.3)",cursor:"pointer",transition:"all .3s",textAlign:"center"}}>
                <span style={{fontFamily:"'Orbitron',monospace",fontSize:".42rem",letterSpacing:".18em",color:i===active?f.accent:"rgba(255,180,0,.35)",display:"block",marginBottom:".25rem"}}>{f.label}</span>
                <span style={{fontFamily:"'Orbitron',monospace",fontSize:".75rem",fontWeight:700,color:i===active?f.accent:"rgba(255,255,255,.4)"}}>{f.value}</span>
              </div>
            ))}
          </div>
        </motion.div>
      </div>
    </section>
  );
}

